    let lo = 24 * 60, hi = 0; TF.forEach(f => { const H = FC().dayHours(f, day); if (H && !H.closed) { lo = Math.min(lo, H.from); hi = Math.max(hi, H.to); } }); if (lo >= hi) { lo = 9 * 60; hi = 18 * 60; } lo = Math.floor(lo / 60) * 60; hi = Math.ceil(hi / 60) * 60; const span = hi - lo; const pct = m => ((m - lo) / span * 100).toFixed(2);
