    const upd = () => { const [fi] = fv(w, 'fr').split('|'); const f = fac(fi); const d = fv(w, 'day'); const sel = w.querySelector('[name=sm]'), au = w.querySelector('[name=aud]'); const cs = sel.value; sel.innerHTML = FC().slots(f, d).map(s => `<option value="${s.sm}" ${String(s.sm) === cs ? 'selected' : ''}>${s.from}</option>`).join('') || '<option value="">운영 안 함</option>'; const ca = au.value; au.innerHTML = f.audience.map(a => `<option value="${a}" ${a === ca ? 'selected' : ''}>${AUD[a]}</option>`).join(''); const q = qTime(f, au.value, d, +sel.value, +fv(w, 'n') || 1); $('#fcQ').textContent = q.error ? '선택한 칸을 확인해 주십시오(운영 시간 · 최대 칸).' : `요금 ${won(q.final)} (${lineTxt(q.lines).join(' · ')}) · 결제는 현장 결제로 기록합니다.`; };
